+/**
+ * A `streamFactory` backed by the real @ag-ui/client 1.0.x `HttpAgent`: the run
+ * goes over HTTP/SSE to the scripted agent, through the client's enforcement,
+ * chunk expansion, verification and interrupt bookkeeping, and every event the
+ * client applies is handed to the chat store as an `AgUiEvent`.
+ *
+ * Each call is recorded (signal, resume[], events received and when), so the
+ * spec can read what the factory saw.
+ */
+import { HttpAgent, type Message, type ResumeEntry } from "@ag-ui/client";
+import type { AgUiEvent, ChatMessage, ChatStreamContext } from "@prometheus-ags/a2ui-react/ag-ui";
+
+export interface StreamEventRecord {
+  type: string;
+  at: number;
+  /** True when the chat store had already stopped reading this stream. */
+  afterConsumerClosed: boolean;
+}
+
+export interface StreamRecord {
+  label: string;
+  url: string;
+  startedAt: number;
+  historyRoles: string[];
+  resume: Array<Record<string, unknown>> | null;
+  /** `HttpAgent.pendingInterrupts` before this run: what the real client parsed from the previous run's outcome. */
+  clientPendingInterruptIds: string[];
+  honoursSignal: boolean;
+  signal: AbortSignal;
+  abortedAt: number | null;
+  transportAborted: boolean;
+  events: StreamEventRecord[];
+  consumerClosedAt: number | null;
+  finished: boolean;
+  error: string | null;
+  /** Ends the transport of a stream that does not honour its signal. */
+  dispose: () => void;
+}
+
+/** The serializable view of a record. */
+export function describeRecord(record: StreamRecord): Record<string, unknown> {
+  return {
+    label: record.label,
+    url: record.url,
+    startedAt: record.startedAt,
+    historyRoles: record.historyRoles,
+    resume: record.resume,
+    clientPendingInterruptIds: record.clientPendingInterruptIds,
+    honoursSignal: record.honoursSignal,
+    signalAborted: record.signal.aborted,
+    abortedAt: record.abortedAt,
+    transportAborted: record.transportAborted,
+    events: record.events,
+    consumerClosedAt: record.consumerClosedAt,
+    finished: record.finished,
+    error: record.error,
+  };
+}
+
+/** The conversation as the run input's `messages`, in AG-UI 1.0 message shape. */
+export function toAgUiMessages(history: readonly ChatMessage[]): Message[] {
+  const messages: Message[] = [];
+  for (const message of history) {
+    if (message.role === "tool") {
+      if (message.toolCallId) {
+        messages.push({ id: message.id, role: "tool", content: message.content, toolCallId: message.toolCallId } as Message);
+      }
+      continue;
+    }
+    if (message.role === "assistant") {
+      messages.push({
+        id: message.id,
+        role: "assistant",
+        content: message.content,
+        ...(message.toolCalls && message.toolCalls.length > 0
+          ? { toolCalls: message.toolCalls.map((call) => ({ id: call.id, type: "function", function: { ...call.function } })) }
+          : {}),
+      } as Message);
+      continue;
+    }
+    messages.push({ id: message.id, role: message.role, content: message.content } as Message);
+  }
+  return messages;
+}
+
+function errorText(cause: unknown): string {
+  return cause instanceof Error ? cause.message : String(cause);
+}
+
+export interface AgentRunOptions {
+  label: string;
+  agent: HttpAgent;
+  history: readonly ChatMessage[];
+  context: ChatStreamContext;
+  /**
+   * Abort the HTTP request when the run's signal aborts (what a consumer
+   * should do). UPG-11's superseded stream sets false on purpose: its transport
+   * stays open, so its later events demonstrably reach the browser and the
+   * store's own guard is what keeps them out of the graph.
+   */
+  honoursSignal: boolean;
+  records: StreamRecord[];
+}
+
+/** Run the agent once and expose the applied events as an async iterable. */
+export function agentRunStream(options: AgentRunOptions): AsyncIterable<AgUiEvent> {
+  const { agent, context } = options;
+  const controller = new AbortController();
+  const queue: AgUiEvent[] = [];
+  let wake: (() => void) | null = null;
+  let done = false;
+  let failure: unknown = null;
+  let consumerClosed = false;
+  const notify = (): void => {
+    const resolve = wake;
+    wake = null;
+    resolve?.();
+  };
+
+  const record: StreamRecord = {
+    label: options.label,
+    url: agent.url,
+    startedAt: performance.now(),
+    historyRoles: options.history.map((message) => message.role),
+    resume: context.resume ?? null,
+    clientPendingInterruptIds: agent.pendingInterrupts.map((interrupt) => interrupt.id),
+    honoursSignal: options.honoursSignal,
+    signal: context.signal,
+    abortedAt: null,
+    transportAborted: false,
+    events: [],
+    consumerClosedAt: null,
+    finished: false,
+    error: null,
+    dispose: () => controller.abort(),
+  };
+  options.records.push(record);
+
+  const onAbort = (): void => {
+    record.abortedAt = performance.now();
+    if (options.honoursSignal) {
+      record.transportAborted = true;
+      controller.abort();
+    }
+  };
+  if (context.signal.aborted) onAbort();
+  else context.signal.addEventListener("abort", onAbort, { once: true });
+
+  agent.setMessages(toAgUiMessages(options.history));
+  agent
+    .runAgent(
+      {
+        abortController: controller,
+        ...(context.resume ? { resume: context.resume as unknown as ResumeEntry[] } : {}),
+      },
+      {
+        onEvent: ({ event }) => {
+          record.events.push({ type: String(event.type), at: performance.now(), afterConsumerClosed: consumerClosed });
+          if (!consumerClosed) {
+            queue.push(event as unknown as AgUiEvent);
+            notify();
+          }
+        },
+      },
+    )
+    .then(
+      () => {
+        record.finished = true;
+        done = true;
+        notify();
+      },
+      (cause: unknown) => {
+        record.error = errorText(cause);
+        failure = cause;
+        done = true;
+        notify();
+      },
+    );
+
+  return {
+    [Symbol.asyncIterator](): AsyncIterator<AgUiEvent> {
+      return {
+        async next(): Promise<IteratorResult<AgUiEvent>> {
+          for (;;) {
+            const event = queue.shift();
+            if (event) return { value: event, done: false };
+            if (failure) throw failure;
+            if (done) return { value: undefined, done: true };
+            await new Promise<void>((resolve) => {
+              wake = resolve;
+            });
+          }
+        },
+        async return(): Promise<IteratorResult<AgUiEvent>> {
+          consumerClosed = true;
+          record.consumerClosedAt = performance.now();
+          queue.length = 0;
+          return { value: undefined, done: true };
+        },
+      };
+    },
+  };
+}
+
+/** A fresh `HttpAgent` on the scripted agent's path. */
+export function scriptedAgent(agentBase: string, path: string, threadId: string): HttpAgent {
+  return new HttpAgent({ url: `${agentBase}/agent/${path}`, threadId });
+}
diff --git a/tests/agui-run-stack/src/graph-probe.ts b/tests/agui-run-stack/src/graph-probe.ts
new file mode 100644
index 00000000..64b150b5
--- /dev/null
+++ b/tests/agui-run-stack/src/graph-probe.ts
@@ -0,0 +1,86 @@
+/**
+ * Read-only probes on the page's entity graph: a per-stream counter of chat
+ * message writes (UPG-11) and plain-JSON snapshots for the digests the spec
+ * records (UPG-10, UPG-12). Nothing here writes to the graph.
+ */
+import type { GraphStore } from "@prometheus-ags/entity-graph-core";
+import {
+  CHAT_CONVERSATION_ENTITY,
+  CHAT_MESSAGE_ENTITY,
+  chatListKey,
+} from "@prometheus-ags/a2ui-react/ag-ui";
+
+export interface MessageWrite {
+  seq: number;
+  bucket: string;
+  conversationId: string;
+  messageId: string;
+  at: number;
+}
+
+export interface MessageWriteCounter {
+  writes: MessageWrite[];
+  countsSince(seq: number): Record<string, number>;
+  stop(): void;
+}
+
+/**
+ * Counts every graph notification in which an `A2uiChatMessage` entity
+ * changed (its object identity, which Immer only replaces on a write), and
+ * attributes it with `bucketOf(conversationId, messageId)`.
+ */
+export function countMessageWrites(
+  store: GraphStore,
+  bucketOf: (conversationId: string, messageId: string) => string,
+): MessageWriteCounter {
+  const writes: MessageWrite[] = [];
+  const stop = store.subscribe((state, previous) => {
+    const next = state.entities[CHAT_MESSAGE_ENTITY] ?? {};
+    const before = previous.entities[CHAT_MESSAGE_ENTITY] ?? {};
+    if (next === before) return;
+    for (const key of new Set([...Object.keys(next), ...Object.keys(before)])) {
+      if (next[key] === before[key]) continue;
+      let conversationId = "?";
+      let messageId = key;
+      try {
+        const tuple = JSON.parse(key) as unknown;
+        if (Array.isArray(tuple) && typeof tuple[0] === "string" && typeof tuple[1] === "string") {
+          [conversationId, messageId] = tuple as [string, string];
+        }
+      } catch {
+        // Keep the raw key; the bucket function sees it unparsed.
+      }
+      writes.push({ seq: writes.length, bucket: bucketOf(conversationId, messageId), conversationId, messageId, at: performance.now() });
+    }
+  });
+  return {
+    writes,
+    countsSince(seq: number): Record<string, number> {
+      const counts: Record<string, number> = {};
+      for (const write of writes.slice(seq)) counts[write.bucket] = (counts[write.bucket] ?? 0) + 1;
+      return counts;
+    },
+    stop,
+  };
+}
+
+/** A conversation as stored in the graph: its id list, message entities and conversation record. */
+export function conversationSnapshot(store: GraphStore, conversationId: string): Record<string, unknown> {
+  const state = store.getState();
+  const ids = state.lists[chatListKey(conversationId)]?.ids ?? [];
+  return {
+    conversationId,
+    listKey: chatListKey(conversationId),
+    ids,
+    messages: ids.map((id) => state.entities[CHAT_MESSAGE_ENTITY]?.[String(id)] ?? null),
+    conversation: state.entities[CHAT_CONVERSATION_ENTITY]?.[conversationId] ?? null,
+  };
+}
+
+/** One entity's stored base, its local patch, and the merged read. */
+export function entitySnapshot(store: GraphStore, type: string, id: string): Record<string, unknown> {
+  const state = store.getState();
+  const base = state.entities[type]?.[id] ?? null;
+  const patch = state.patches[type]?.[id] ?? null;
+  return { type, id, base, patch, merged: base ? { ...base, ...(patch ?? {}) } : null };
+}
diff --git a/tests/agui-run-stack/src/main.ts b/tests/agui-run-stack/src/main.ts
new file mode 100644
index 00000000..22fc2d70
--- /dev/null
+++ b/tests/agui-run-stack/src/main.ts
@@ -0,0 +1,60 @@
+/**
+ * Entry of the UPG-10/11/12 page. `?scenario=upg10|upg11|upg12&agent=<url>`
+ * picks the scenario and the scripted agent; each scenario gets a fresh,
+ * isolated graph (`createGraphStore`) passed to the chat components through
+ * their `graphStore` option. The spec drives the DOM and reads
+ * `window.__aguiRunStack.snapshot()`.
+ */
+import { createRoot } from "react-dom/client";
+import { createGraphStore, type GraphStore } from "@prometheus-ags/entity-graph-core";
+import type { ReactElement } from "react";
+import { setupUpg10 } from "./upg10.js";
+import { setupUpg11 } from "./upg11.js";
+import { setupUpg12 } from "./upg12.js";
+
+declare global {
+  interface Window {
+    __aguiRunStack: {
+      scenario: string;
+      snapshot(): Record<string, unknown>;
+      dispose(): void;
+    };
+  }
+}
+
+const params = new URLSearchParams(window.location.search);
+const scenario = params.get("scenario") ?? "";
+const agentBase = params.get("agent") ?? "";
+const container = document.getElementById("agui-run-stack-root");
+
+function fail(message: string): never {
+  document.documentElement.dataset.aguiRunStackError = message;
+  throw new Error(message);
+}
+
+if (!container) fail("missing #agui-run-stack-root");
+if (!/^https?:\/\//.test(agentBase)) fail("the agent query parameter must be the scripted agent's http URL");
+
+const graph = createGraphStore();
+interface ScenarioHandle {
+  element: ReactElement;
+  snapshot(): Record<string, unknown>;
+  dispose?(): void;
+}
+
+const setups: Record<string, (graph: GraphStore, agentBase: string) => ScenarioHandle> = {
+  upg10: setupUpg10,
+  upg11: setupUpg11,
+  upg12: setupUpg12,
+};
+const setup = Object.hasOwn(setups, scenario) ? setups[scenario] : undefined;
+if (!setup) fail(`unknown scenario ${JSON.stringify(scenario)}`);
+
+const handle = setup(graph, agentBase);
+window.__aguiRunStack = {
+  scenario,
+  snapshot: () => handle.snapshot(),
+  dispose: () => handle.dispose?.(),
+};
+createRoot(container as HTMLElement).render(handle.element);
+document.documentElement.dataset.aguiRunStackReady = "true";
diff --git a/tests/agui-run-stack/src/upg10.ts b/tests/agui-run-stack/src/upg10.ts
new file mode 100644
index 00000000..d1487061
--- /dev/null
+++ b/tests/agui-run-stack/src/upg10.ts
@@ -0,0 +1,61 @@
+/**
+ * UPG-10: an AG-UI 1.0 run streamed by @ag-ui/client drives EntityChat through
+ * the graph. Three views share one graph:
+ * - `chat`   EntityChat on the conversation the user talks in;
+ * - `mirror` a second EntityChat on the SAME conversation id (it never sends);
+ * - `other`  EntityChat on a DIFFERENT conversation id (the negative control),
+ *            which later sends its own probe run to show it renders live.
+ */
+import { createElement as h, type ReactElement } from "react";
+import type { GraphStore } from "@prometheus-ags/entity-graph-core";
+import { EntityChat, type ChatStreamFactory } from "@prometheus-ags/a2ui-react/ag-ui";
+import { agentRunStream, describeRecord, scriptedAgent, type StreamRecord } from "./agent-stream.js";
+import { conversationSnapshot } from "./graph-probe.js";
+import fixtures from "../fixtures.json";
+
+const f = fixtures.upg10;
+
+export interface Upg10Handle {
+  element: ReactElement;
+  snapshot(): Record<string, unknown>;
+}
+
+export function setupUpg10(graph: GraphStore, agentBase: string): Upg10Handle {
+  const records: StreamRecord[] = [];
+  const mirrorCalls: number[] = [];
+  const mainAgent = scriptedAgent(agentBase, "upg10", f.conversationId);
+  const probeAgent = scriptedAgent(agentBase, "upg10-probe", f.otherConversationId);
+
+  const mainFactory: ChatStreamFactory = (history, context) =>
+    agentRunStream({ label: "main", agent: mainAgent, history, context, honoursSignal: true, records });
+  const probeFactory: ChatStreamFactory = (history, context) =>
+    agentRunStream({ label: "probe", agent: probeAgent, history, context, honoursSignal: true, records });
+  // The mirror only reads; a call here would mean the second view started a run.
+  const mirrorFactory: ChatStreamFactory = () => {
+    mirrorCalls.push(performance.now());
+    throw new Error("the mirror view must not start a run");
+  };
+
+  const element = h(
+    "div",
+    { className: "agui-run-stack agui-run-stack--upg10" },
+    h("section", { "data-view": "chat", "aria-label": "Chat view" },
+      h(EntityChat, { sessionId: f.conversationId, graphStore: graph, streamFactory: mainFactory })),
+    h("section", { "data-view": "mirror", "aria-label": "Second view of the same conversation" },
+      h(EntityChat, { sessionId: f.conversationId, graphStore: graph, streamFactory: mirrorFactory })),
+    h("section", { "data-view": "other", "aria-label": "View of a different conversation" },
+      h(EntityChat, { sessionId: f.otherConversationId, graphStore: graph, streamFactory: probeFactory })),
+  );
+
+  return {
+    element,
+    snapshot: () => ({
+      graph: {
+        main: conversationSnapshot(graph, f.conversationId),
+        other: conversationSnapshot(graph, f.otherConversationId),
+      },
+      streams: records.map(describeRecord),
+      mirrorFactoryCalls: mirrorCalls.length,
+    }),
+  };
+}
diff --git a/tests/agui-run-stack/src/upg11.ts b/tests/agui-run-stack/src/upg11.ts
new file mode 100644
index 00000000..cb83166a
--- /dev/null
+++ b/tests/agui-run-stack/src/upg11.ts
@@ -0,0 +1,123 @@
+/**
+ * UPG-11: cancellation stops superseded streams. Two conversations on one
+ * graph, each driven by `useChatSession` (EntityChat disables its input while a
+ * run is in flight, so the second send needs the hook):
+ * - `superseded` (conversation X): "send first" starts the slow stream A,
+ *   "send second" supersedes it with stream B;
+ * - `control` (conversation Y): stream C runs alongside and is never superseded.
+ *
+ * A graph write counter attributes every chat message write to its stream by
+ * message id. The spec releases the agent's gate after the second send, so A and
+ * C both emit their later events; A's must cause zero writes, C's must write.
+ */
+import { createElement as h, type ReactElement } from "react";
+import type { GraphStore } from "@prometheus-ags/entity-graph-core";
+import { useChatSession, type ChatMessage, type ChatStreamFactory } from "@prometheus-ags/a2ui-react/ag-ui";
+import { agentRunStream, describeRecord, scriptedAgent, type StreamRecord } from "./agent-stream.js";
+import { conversationSnapshot, countMessageWrites } from "./graph-probe.js";
+import fixtures from "../fixtures.json";
+
+const f = fixtures.upg11;
+
+export interface Upg11Handle {
+  element: ReactElement;
+  snapshot(): Record<string, unknown>;
+  dispose(): void;
+}
+
+function bucketOf(_conversationId: string, messageId: string): string {
+  if (messageId.startsWith("a-")) return "first";
+  if (messageId.startsWith("b-")) return "second";
+  if (messageId.startsWith("c-")) return "control";
+  return "user";
+}
+
+function MessageList({ messages }: { messages: ChatMessage[] }): ReactElement {
+  return h(
+    "ol",
+    { className: "agui-run-stack__messages" },
+    ...messages.map((message) =>
+      h("li", { key: message.id, "data-message-id": message.id, "data-role": message.role }, message.content)),
+  );
+}
+
+export function setupUpg11(graph: GraphStore, agentBase: string): Upg11Handle {
+  const records: StreamRecord[] = [];
+  const counter = countMessageWrites(graph, bucketOf);
+  const marks: { supersede: { seq: number; at: number } | null } = { supersede: null };
+  let supersededCalls = 0;
+
+  const supersededFactory: ChatStreamFactory = (history, context) => {
+    supersededCalls += 1;
+    const first = supersededCalls === 1;
+    return agentRunStream({
+      label: first ? "first" : "second",
+      agent: scriptedAgent(agentBase, first ? "upg11-a" : "upg11-b", f.supersededConversationId),
+      history,
+      context,
+      honoursSignal: !first,
+      records,
+    });
+  };
+  const controlFactory: ChatStreamFactory = (history, context) =>
+    agentRunStream({
+      label: "control",
+      agent: scriptedAgent(agentBase, "upg11-c", f.controlConversationId),
+      history,
+      context,
+      honoursSignal: true,
+      records,
+    });
+
+  function Harness(): ReactElement {
+    const superseded = useChatSession({ sessionId: f.supersededConversationId, graphStore: graph, streamFactory: supersededFactory });
+    const control = useChatSession({ sessionId: f.controlConversationId, graphStore: graph, streamFactory: controlFactory });
+    return h(
+      "div",
+      { className: "agui-run-stack agui-run-stack--upg11" },
+      h("section", { "data-view": "superseded", "data-run-status": superseded.session.runStatus, "aria-label": "Superseded conversation" },
+        h("button", { type: "button", id: "send-first", onClick: () => void superseded.sendMessage(f.first.userText) }, "Send first"),
+        h("button", {
+          type: "button",
+          id: "send-second",
+          onClick: () => {
+            // Taken before sendMessage aborts the first run's signal.
+            marks.supersede = { seq: counter.writes.length, at: performance.now() };
+            void superseded.sendMessage(f.second.userText);
+          },
+        }, "Send second"),
+        h(MessageList, { messages: superseded.session.messages })),
+      h("section", { "data-view": "control", "data-run-status": control.session.runStatus, "aria-label": "Control conversation" },
+        h("button", { type: "button", id: "send-control", onClick: () => void control.sendMessage(f.control.userText) }, "Send control"),
+        h(MessageList, { messages: control.session.messages })),
+    );
+  }
+
+  return {
+    element: h(Harness),
+    snapshot: () => {
+      const supersede = marks.supersede;
+      return {
+        supersede,
+        writes: counter.writes,
+        writesBeforeSupersede: supersede ? countBuckets(counter.writes.slice(0, supersede.seq)) : null,
+        writesAfterSupersede: supersede ? counter.countsSince(supersede.seq) : null,
+        streams: records.map(describeRecord),
+        graph: {
+          superseded: conversationSnapshot(graph, f.supersededConversationId),
+          control: conversationSnapshot(graph, f.controlConversationId),
+        },
+      };
+    },
+    dispose: () => {
+      for (const record of records) record.dispose();
+      counter.stop();
+    },
+  };
+}
+
+function countBuckets(writes: ReadonlyArray<{ bucket: string }>): Record<string, number> {
+  const counts: Record<string, number> = {};
+  for (const write of writes) counts[write.bucket] = (counts[write.bucket] ?? 0) + 1;
+  return counts;
+}
diff --git a/tests/agui-run-stack/src/upg12.ts b/tests/agui-run-stack/src/upg12.ts
new file mode 100644
index 00000000..f7fb055b
--- /dev/null
+++ b/tests/agui-run-stack/src/upg12.ts
@@ -0,0 +1,97 @@
+/**
+ * UPG-12: interrupt approvals through the entity action policy. One EntityChat
+ * per case, each on its own conversation and its own `HttpAgent` (so the real
+ * client tracks that thread's pending interrupts and checks the resume run
+ * covers them). All chats share one graph and one policy built with the
+ * package's `createEntityGraphA2uiActionPolicy`; its `onDecision` is the audit.
+ */
+import { createElement as h, type ReactElement } from "react";
+import type { GraphStore } from "@prometheus-ags/entity-graph-core";
+import {
+  createEntityGraphA2uiActionPolicy,
+  type A2uiActionDecision,
+  type EntityGraphA2uiActionName,
+} from "@prometheus-ags/a2ui-react";
+import { EntityChat, type ChatInterrupt, type ChatResumeEntry, type ChatStreamFactory } from "@prometheus-ags/a2ui-react/ag-ui";
+import { agentRunStream, describeRecord, scriptedAgent, type StreamRecord } from "./agent-stream.js";
+import { conversationSnapshot, entitySnapshot } from "./graph-probe.js";
+import fixtures from "../fixtures.json";
+
+const f = fixtures.upg12;
+export const UPG12_CASES = Object.keys(f.cases) as Array<keyof typeof f.cases>;
+
+export interface Upg12Handle {
+  element: ReactElement;
+  snapshot(): Record<string, unknown>;
+}
+
+function conversationOf(caseName: string): string {
+  return `upg12-${caseName}`;
+}
+
+function describeDecision(decision: A2uiActionDecision): Record<string, unknown> {
+  const action = decision.action;
+  return {
+    status: decision.status,
+    name: action?.name ?? null,
+    surfaceId: action?.surfaceId ?? null,
+    sourceComponentId: action?.sourceComponentId ?? null,
+    context: action?.context ?? null,
+    ...(decision.status === "denied" ? { code: decision.code, reason: decision.reason } : {}),
+  };
+}
+
+export function setupUpg12(graph: GraphStore, agentBase: string): Upg12Handle {
+  const state = graph.getState();
+  for (const seed of f.seed) state.upsertEntity(seed.type, seed.id, seed.data);
+
+  const records: StreamRecord[] = [];
+  const audit: Array<Record<string, unknown>> = [];
+  const interruptDecisions: Array<Record<string, unknown>> = [];
+  const policy = createEntityGraphA2uiActionPolicy({
+    graphStore: graph,
+    entities: Object.fromEntries(
+      Object.entries(f.policy).map(([type, rule]) => [type, {
+        actions: rule.actions as EntityGraphA2uiActionName[],
+        fields: rule.fields,
+      }]),
+    ),
+    authorize: () => ({ allowed: true }),
+    onDecision: (decision) => {
+      audit.push({ seq: audit.length, at: performance.now(), ...describeDecision(decision) });
+    },
+  });
+
+  const chats = UPG12_CASES.map((caseName) => {
+    const agent = scriptedAgent(agentBase, `upg12/${caseName}`, conversationOf(caseName));
+    const streamFactory: ChatStreamFactory = (history, context) =>
+      agentRunStream({ label: `upg12-${caseName}`, agent, history, context, honoursSignal: true, records });
+    const onInterruptDecision = (interrupt: ChatInterrupt, entry: ChatResumeEntry, decision?: A2uiActionDecision): void => {
+      interruptDecisions.push({
+        case: caseName,
+        interruptId: interrupt.id,
+        entry,
+        policyDecision: decision ? describeDecision(decision) : null,
+      });
+    };
+    return h("section", { key: caseName, "data-view": `upg12-${caseName}`, "aria-label": `Interrupt case ${caseName}` },
+      h(EntityChat, {
+        sessionId: conversationOf(caseName),
+        graphStore: graph,
+        streamFactory,
+        actionPolicy: policy,
+        onInterruptDecision,
+      }));
+  });
+
+  return {
+    element: h("div", { className: "agui-run-stack agui-run-stack--upg12" }, ...chats),
+    snapshot: () => ({
+      entities: Object.fromEntries(f.seed.map((seed) => [`${seed.type}:${seed.id}`, entitySnapshot(graph, seed.type, seed.id)])),
+      audit,
+      interruptDecisions,
+      streams: records.map(describeRecord),
+      conversations: Object.fromEntries(UPG12_CASES.map((caseName) => [caseName, conversationSnapshot(graph, conversationOf(caseName))])),
+    }),
+  };
+}
